	private static List<Long> multiplicities(LeftJoinCursor cursor) throws Exception {
		List<Long> values = new ArrayList<>();
		while (cursor.next()) {
			values.add(cursor.multiplicity());
		}
		return values;
	}

	private static RowCursor weightedLeft(RowState row, int slot, long[] values, long[] weights) {
		if (values.length != weights.length) {
			throw new IllegalArgumentException("left values and weights must align");
		}
		return new FactorizedRowCursor() {
			final int mark = row.mark();
			int current = -1;

			@Override
			public boolean next() {
				row.rollback(mark);
				current++;
				return current < values.length && (slot < 0 || row.bindOrCheckTerm(slot, values[current]));
			}

			@Override
			public long multiplicity() {
				return current < 0 || current >= weights.length ? 1L : weights[current];
			}

			@Override
			public void close() {
				row.rollback(mark);
			}
		};
	}

	private static SlotPlan weightedRight(int slot, long value, long weight, AtomicInteger opens) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) {
				opens.incrementAndGet();
				return new FactorizedRowCursor() {
					final int mark = row.mark();
					boolean emitted;

					@Override
					public boolean next() {
						row.rollback(mark);
						if (emitted) {
							return false;
						}
						emitted = true;
						return slot < 0 || row.bindOrCheckTerm(slot, value);
					}

					@Override
					public long multiplicity() {
						return weight;
					}

					@Override
					public void close() {
						row.rollback(mark);
					}
				};
			}

			@Override
			public long producedMask() {
				return slot < 0 ? 0L : 1L << slot;
			}
		};
	}

